-- black-mahogany-construction-best-civil-engineering-concrete-pumping-earthworks-g-waterkloof-glen (owner)
UPDATE businesses SET description = 'Black Mahogany Construction is a civil engineering and capital-project construction company established in 2009, with its Pretoria office at the Park Lane West Building, 194 Bancor Avenue, Waterkloof Glen. The company carries out civil works including setting out, excavations, foundations, platforms, parking lots and roads, together with engineering fill and wet works. It also produces volume calculations, construction diagrams and plans, and undertakes infrastructure rehabilitation, urban development and drone surveying, alongside high-voltage works and capital-project delivery. Its client base spans businesses, developers, contractors and public-sector and parastatal bodies, including work for Transnet Capital Projects and WBHO. In 2025 the company was engaged on the Transnet Maydon Wharf berth rehabilitation project, one of its more recent capital works. Black Mahogany Construction serves developers and contractors needing civil engineering and infrastructure delivery on both private and public-sector projects.', description_enriched_at = datetime('now') WHERE slug = 'black-mahogany-construction-best-civil-engineering-concrete-pumping-earthworks-g-waterkloof-glen' AND description = 'Black Mahogany Construction, established in 2009 and based in Waterkloof Glen, provides civil engineering and capital-project services including foundations, road and drainage infrastructure rehabilitation, drone surveys and high-voltage switchgear delivery.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
