UPDATE businesses SET description = 'Black Ox Holdings is a Black-owned investment holding company with its office at Building I, Hertford Office Park, 90 Bekker Road, Midrand. The group holds interests across technology, renewable energy, communications and education businesses rather than operating as a single consumer-facing outlet. Its portfolio of group companies includes OneConnect Solutions, OneConnect Communications, OneConnect Marketing, OneConnect Academy and OneConnect Industries, spanning technology services, communications, renewable-energy ventures and education-related operations. As a holding company, Black Ox Holdings manages and grows this group of businesses rather than trading directly with the public. It serves the businesses within its portfolio and the sectors they operate in, including technology, communications and renewable energy, from its Midrand office in Gauteng.', description_enriched_at = datetime('now') WHERE slug = 'black-ox-holdings-eco-park' AND description = 'Black Ox Holdings is a Black-owned investment holding company at Eco Park with a portfolio of technology, renewable-energy, communications and education businesses including OneConnect Solutions, OneConnect Communications and OneConnect Academy.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
