UPDATE businesses SET description = 'BMW Menlyn is an authorised BMW dealership at the corner of Garsfontein Road and Lois Avenue in Menlyn, trading as the LMG Menlyn Authorised BMW and MINI Agency under Legacy Motor Group. The dealership sells new BMW vehicles alongside BMW Approved used vehicles, and offers vehicle finance to private buyers. Its aftersales department supports BMW owners with servicing and maintenance, including the option to schedule a service appointment through BMW''s official retailer channels. As part of the Legacy Motor Group network, the dealership also handles MINI sales and service alongside its BMW operations at the same Menlyn site. It is open Monday to Friday from 7:30am to 5:30pm and Saturdays from 8:30am to 1pm, closed Sundays. The dealership serves private vehicle buyers across Pretoria looking for new or approved used BMWs, finance or ongoing servicing.', description_enriched_at = datetime('now') WHERE slug = 'bmw-menlyn' AND description = 'BMW Menlyn is an official BMW dealership at the corner of Garsfontein Road and Lois Avenue in Newlands, selling new and used BMW vehicles alongside financing, parts and after-sales service.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
