UPDATE businesses SET description = '3@1 Wonderpark is a branch of the 3@1 Business Centre franchise, trading as Wonderpark 3@1 at Shop 114, Wonderpark Shopping Centre, on the corner of Old Brits and Heinrich Avenue, Karenpark. The branch is listed on the 3@1 franchise''s official store locator, confirming it as a current, operating branch within the national network. Like other 3@1 outlets, it offers digital and photographic printing and document-related services, along with domestic and international courier and parcel services operated in partnership with DHL and Fujifilm. The branch serves individuals, students, households and businesses in Karenpark and the surrounding Wonderpark area who need printing, document or courier services. Customers can visit the Wonderpark Shopping Centre location directly for in-store printing and courier drop-off.', description_enriched_at = datetime('now') WHERE slug = '3-1-wonderpark-karenpark' AND description = '3@1 Wonderpark is a branch of the 3@1 Business Centre franchise, offering digital print, photographic printing and domestic and international courier services in partnership with DHL and Fujifilm.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
