UPDATE businesses SET description = 'Accounting Avenue is a professional accounting practice based at 343 Umgeni Street, Erasmuskloof, Pretoria, with around 20 years of experience in the field. The practice offers accounting, tax assistance, auditing, bookkeeping and management financial reporting, alongside broader financial consulting support. It works with clients to analyse financial performance, identify bottlenecks in their operations and improve overall financial management. Accounting Avenue serves businesses of different sizes and across different industries, as well as individuals needing personal accounting or tax support. Its Erasmuskloof office is open from 8am to 5pm on weekdays. The practice''s combination of long-standing experience and a broad service range, from day-to-day bookkeeping to in-depth financial analysis, suits both established businesses and individuals seeking ongoing accounting support in Pretoria East.', description_enriched_at = datetime('now') WHERE slug = 'accounting-avenue-erasmuskloof' AND description = 'Accounting Avenue is an accounting firm with roughly 20 years of experience, offering accounting, tax, payroll and statutory compliance services including CIPC filings and tax registrations from its Erasmuskloof office.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
